import{_ as t,a as o,a3 as a,o as n}from"./chunks/framework.edeurCMZ.js";const u=JSON.parse('{"title":"The @ecl Participant in Copilot","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/userdoc/copilot/eclParticipantinCopilot.md","filePath":"devdoc/userdoc/copilot/eclParticipantinCopilot.md","lastUpdated":1787329496000}'),r={name:"devdoc/userdoc/copilot/eclParticipantinCopilot.md"};function i(s,e,c,d,l,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="the-ecl-participant-in-copilot" tabindex="-1">The <code>@ecl</code> Participant in Copilot <a class="header-anchor" href="#the-ecl-participant-in-copilot" aria-label="Permalink to &quot;The `@ecl` Participant in Copilot&quot;">​</a></h1><p>The <strong><code>@ecl</code></strong> participant in the ECL Extension for VS Code enhances answers about ECL in several key ways.</p><h2 id="how-to-use-it" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h2><p>In VS Code&#39;s Copilot chat window, begin your chat with <code>@ecl</code>. This adds the participant to the conversation.</p><p><strong>Note:</strong> You must have the ECL extension installed and enabled.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li><p><strong>Documentation Retrieval</strong> — When you ask an ECL question, the participant searches the official HPCC Systems® ECL documentation and retrieves relevant reference material (ECL Language Reference, ECL Programmer&#39;s Guide, ECL Standard Library Reference, etc.). This grounds answers in <strong>authoritative sources</strong> rather than general knowledge.</p></li><li><p><strong>Tool Access</strong> — The participant can use specialized tools to:</p><ul><li><strong>Look up ECL syntax, functions, and keywords</strong> from the documentation</li><li><strong>Search and inspect workunits</strong> on a connected HPCC Platform</li><li><strong>Search logical files</strong> on the cluster</li><li><strong>Syntax-check ECL code</strong> you provide</li></ul></li><li><p><strong>Contextual Awareness</strong> — It considers your active editor content and workspace, so answers can be tailored to what you&#39;re actually working on.</p></li></ol><h2 id="why-this-produces-better-answers" tabindex="-1">Why This Produces Better Answers <a class="header-anchor" href="#why-this-produces-better-answers" aria-label="Permalink to &quot;Why This Produces Better Answers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Without <code>@ecl</code></th><th>With <code>@ecl</code></th></tr></thead><tbody><tr><td>Generic LLM knowledge (may be outdated or inaccurate)</td><td>Grounded in official, current ECL documentation</td></tr><tr><td>Cannot inspect your cluster</td><td>Can query workunits and logical files directly</td></tr><tr><td>Cannot validate code</td><td>Can syntax-check your ECL snippets</td></tr><tr><td>May fabricate URLs or function signatures</td><td>Uses only verified documentation URLs and content</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>If you ask about index compression options, the participant retrieves the exact <code>BUILDINDEX</code> documentation entry — including the <code>COMPRESSED</code> option variants (LZW, inplace, lz4, lz4hc, etc.), their syntax, and examples — and builds its answer from that, rather than relying on potentially stale training data.</p><p>It also provides links to the relevant topics in the online ECL Language Reference.</p><p>In short, <strong><code>@ecl</code></strong> acts as a bridge between the AI and the real ECL ecosystem — documentation, your cluster, and your code — so you get accurate, actionable answers.</p><p>See also: <a href="./UsingWorkspace.html">Why <code>@workspace</code> matters in Copilot Chat</a>.</p>',14)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
